        frame_index = 0
        i = 0
        while i < len(self.rolls) and frame_index < 9:
            if self.rolls[i] == 10:
                i += 1
            else:
                i += 2
            frame_index += 1

        if frame_index < 9:
            # still within frames 1-9
            if i < len(self.rolls) and self.rolls[i] != 10:
                # second throw of a non-strike frame
                if self.rolls[i] + pins > 10:
                    return False
            return True

        # in the tenth frame
        tenth = self.rolls[i:]
